/** The third-party notices (generated by `just notices`): each licence text, and the software that comes under it. */
export type NoticePackage = { name: string; version: string; url: string; note?: string };
export type NoticeGroup = { license: string; text: string; packages: NoticePackage[] };

/** One piece of software with its licence, ready to list. */
export type Notice = NoticePackage & { /** Unique per row (a package with several licence files, or one text used twice, appears more than once). */ id: number; license: string; text: string };

/** Every piece of software, one row each, in name order. One that has several licence files gets a row for each. */
export function flatten(groups: NoticeGroup[]): Notice[] {
  return groups
    .flatMap((g) => g.packages.map((p) => ({ ...p, license: g.license, text: g.text })))
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }) || a.version.localeCompare(b.version))
    .map((n, id) => ({ ...n, id }));
}

/** Does this piece of software match what was typed (its name or licence, ignoring case)? Nothing typed matches all. */
export function matches(n: Notice, query: string): boolean {
  const q = query.trim().toLowerCase();
  return q === '' || n.name.toLowerCase().includes(q) || n.license.toLowerCase().includes(q);
}

/** The line under the version: the commit it was built from, and a warning when it had uncommitted changes. */
export function buildLine(info: { commit: string; modified: boolean } | null): string {
  if (!info || info.commit === '') return '';
  return info.modified ? `Build ${info.commit} (with changes not yet committed)` : `Build ${info.commit}`;
}
